window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f7394ae5ff5a1923"]={"versions": [{"id": "FIG-f7394ae5ff5a1923", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FrNm_Init</code>) im Kontext der AUTOSAR Classic Platform (Communication Stack / Network Management). Es visualisiert den Initialisierungsablauf des FlexRay Network Management Moduls (<code>FrNm</code>) durch den generischen Network Management Coordinator (<code>Nm</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten / Lifelines</strong>:</li>\n<li><code>Nm:Nm</code>: Instanz bzw. Rolle des generischen AUTOSAR Network Management Interface / Coordinators.</li>\n<li><code>FrNm:FrNm</code>: Instanz bzw. Rolle des FlexRay Network Management Moduls.</li>\n<li><strong>Schnittstellen & Parameter</strong>:</li>\n<li>Synchrone Funktionsschnittstelle <code>FrNm_Init(FrNm_BusNm_ConfigType )</code> zur Übergabe des Konfigurationsdaten-Typs an das FlexRay-NM-Modul.</li>\n<li>Asynchroner bzw. synchroner Rückkehrpfad <code>FrNm_Init</code>.</li>\n<li><strong>Zustandssymbol</strong>:</li>\n<li><code>Bus Sleep Mode</code>: Zustand/Modus des <code>FrNm</code>-Moduls nach erfolgter Initialisierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das Modul <code>Nm</code> initiiert den Kontrollfluss durch Aufruf von <code>FrNm_Init(FrNm_BusNm_ConfigType )</code> an der Lebenslinie von <code>FrNm</code>.</li>\n<li><code>FrNm</code> verarbeitet den Initialisierungsaufruf im Rahmen eines Aktivierungsbalkens.</li>\n<li>Nach Abschluss der Initialisierung kehrt die Ausführung via Rückkehrpfeil <code>FrNm_Init</code> zu <code>Nm</code> zurück.</li>\n<li><code>FrNm</code> befindet sich am Ende der Sequenz im Zustand <code>Bus Sleep Mode</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindlicher Ablauf für die Initialisierungsreihenfolge des FlexRay-Netzwerkmanagements durch das NM-Interface.</li>\n<li>Implementierer müssen sicherstellen, dass <code>FrNm_Init</code> den Konfigurationsdatensatz entgegennimmt und das Modul deterministisch in den Startzustand <code>Bus Sleep Mode</code> überführt, bevor weitere NM-Operationen zugelassen werden.</li>\n</ul>"}, {"id": "FIG-e3273fed0cd4a34a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd FrNm_Init</code>) im Kontext der AUTOSAR Classic Platform (Communication Stack / Network Management). Es visualisiert den Initialisierungsablauf des FlexRay Network Management Moduls (<code>FrNm</code>) durch den generischen Network Management Coordinator (<code>Nm</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten / Lifelines</strong>:</li>\n<li><code>«module» Nm::Nm</code>: Modul des generischen AUTOSAR Network Management.</li>\n<li><code>«module» FrNm::FrNm</code>: Modul des FlexRay Network Management.</li>\n<li><strong>Schnittstellen & Parameter</strong>:</li>\n<li>Funktionsaufruf <code>FrNm_Init(nmConfigPtr)</code> zur Übergabe des Konfigurationszeigers an das FlexRay-NM-Modul.</li>\n<li>Rückkehrpfad <code>FrNm_Init</code>.</li>\n<li><strong>Zustandssymbol</strong>:</li>\n<li><code>Bus Sleep Mode</code>: Zustand des <code>FrNm</code>-Moduls nach Abschluss der Initialisierung.</li>\n<li><strong>Dokumentationsannotationen</strong>:</li>\n<li>Notizfeld mit Statusvermerk <code>Status: proposed</code> und <code>Comments:</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das Modul <code>Nm::Nm</code> ruft <code>FrNm_Init(nmConfigPtr)</code> auf der Lebenslinie von <code>FrNm::FrNm</code> auf.</li>\n<li><code>FrNm::FrNm</code> führt die Initialisierung aus (Aktivierungsbalken).</li>\n<li>Die Steuerungsrückgabe erfolgt über die Rückkehrnachricht <code>FrNm_Init</code> an <code>Nm::Nm</code>.</li>\n<li><code>FrNm::FrNm</code> nimmt nach der Initialisierung den Zustand <code>Bus Sleep Mode</code> ein.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Spezifikation der Initialisierungsschnittstelle von <code>FrNm</code> mit Zeigerübergabe (<code>nmConfigPtr</code>).</li>\n<li>Der Vermerk <code>Status: proposed</code> kennzeichnet den Spezifikationsentwurf.</li>\n<li>Das Modul muss nach Rückkehr aus <code>FrNm_Init</code> zuverlässig im <code>Bus Sleep Mode</code> verharren, bis weitere NM-Ereignisse eintreffen.</li>\n</ul>"}], "trans": [{"from": "FIG-f7394ae5ff5a1923", "to": "FIG-e3273fed0cd4a34a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Aufrufparameter <code>FrNm_Init</code></strong>: Die Signatur des Initialisierungsaufrufs ändert sich von <code>FrNm_Init(FrNm_BusNm_ConfigType )</code> zu <code>FrNm_Init(nmConfigPtr)</code>.</li>\n<li><strong>Modul-Stereotypen</strong>: Die Lifelines <code>Nm:Nm</code> und <code>FrNm:FrNm</code> erhalten den UML-Stereotyp <code>«module»</code> sowie die C++-Namespace-Notation <code>Nm::Nm</code> und <code>FrNm::FrNm</code>.</li>\n<li><strong>Diagramm-Metadaten</strong>: Ein Notiz-Element mit dem Inhalt <code>Status: proposed / Comments:</code> ist unten links ergänzt.</li>\n</ul>"}]};
